ON CONFLICT(id) DO UPDATE SET
  provider = excluded.provider,
  upstream_model_id = excluded.upstream_model_id,
  display_name = excluded.display_name,
  context_length = excluded.context_length,
  max_output_tokens = excluded.max_output_tokens,
  metadata_json = excluded.metadata_json,
  input_price = excluded.input_price,
  output_price = excluded.output_price,
  markup_rate = excluded.markup_rate,
  cached_input_price = excluded.cached_input_price,
  cache_write_price = excluded.cache_write_price,
  long_context_threshold_tokens = excluded.long_context_threshold_tokens,
  long_context_input_price = excluded.long_context_input_price,
  long_context_cached_input_price = excluded.long_context_cached_input_price,
  long_context_cache_write_price = excluded.long_context_cache_write_price,
  long_context_output_price = excluded.long_context_output_price;
